#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.."&&pwd)";. "$ROOT/scripts/tests/fair_launch_local_e2e_test_cleanup.sh";STATE_ROOT="$(jc_fl_test_root_create JC_FL_TEST_START_FAULT_V1)";ACTIVE='';ACTIVE_PROCESS=''
cleanup(){ local original=$? ok=1;set +e;if [ -n "$ACTIVE_PROCESS" ]&&[ -f "$ACTIVE_PROCESS" ];then jc_fl_test_process_remove "$ACTIVE_PROCESS" TERM||ok=0;fi;if [ -n "$ACTIVE" ]&&[ -d "$ACTIVE" ];then jc_fl_test_run_cleanup "$ACTIVE"||ok=0;fi;if [ "$ok" = 1 ];then jc_fl_test_root_finalize "$STATE_ROOT"||ok=0;fi;if [ "$ok" != 1 ];then echo "start_fault_test: cleanup retained evidence at $ACTIVE" >&2;fi;[ "$original" -ne 0 ]&&return "$original";[ "$ok" = 1 ];};trap cleanup EXIT
fail(){ echo "fair_launch_local_e2e_start_fault_test: FAIL: $*" >&2;exit 1;}
for point in after_redis_daemonized after_redis_pid_read;do
 set +e;JC_FL_E2E_STATE_ROOT="$STATE_ROOT" JC_FL_E2E_TEST_FAIL_AT="$point" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$STATE_ROOT/$point.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ]||fail "$point did not fail";d="$(find "$STATE_ROOT" -mindepth 1 -maxdepth 1 -type d|head -1)";ACTIVE="$d";[ -n "$d" ]&&[ ! -e "$d/redis/process.json" ]&&[ ! -L "$d/redis/process.json" ]||fail "$point missing-authority fixture";grep -Fq redis-authority-missing-after-launch-attempt "$d/evidence/start-failure.json"||fail "$point missing-authority reason";set +e;jc_fl_test_run_cleanup "$d";cleanup_rc=$?;set -e;[ "$cleanup_rc" -ne 0 ]&&[ -d "$d" ]||fail "$point cleanup did not fail closed";jc_fl_test_redis_publish_recovery_authority "$d"||fail "$point recovery authority publication";jc_fl_test_run_cleanup "$d"||fail "$point strict recovery cleanup";ACTIVE=''
done
set +e;JC_FL_E2E_STATE_ROOT="$STATE_ROOT" JC_FL_E2E_TEST_FAIL_AT=after_redis_authority_invalid bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$STATE_ROOT/after_redis_authority_invalid.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ]||fail 'after_redis_authority_invalid did not fail';d="$(find "$STATE_ROOT" -mindepth 1 -maxdepth 1 -type d|head -1)";ACTIVE="$d";[ "$(stat -Lc %a "$d/redis/process.json")" = 640 ]||fail 'invalid Redis authority fixture mode';grep -Fq redis-ownership-ambiguous "$d/evidence/start-failure.json"||fail 'invalid Redis authority reason';set +e;jc_fl_test_run_cleanup "$d";cleanup_rc=$?;set -e;[ "$cleanup_rc" -ne 0 ]&&[ -d "$d" ]||fail 'invalid Redis authority cleanup did not fail closed';chmod 600 "$d/redis/process.json";python3 "$ROOT/scripts/fair-launch/local-e2e/redis-process-record.py" verify "$d/redis/process.json">/dev/null||fail 'restored Redis authority invalid';jc_fl_test_run_cleanup "$d"||fail 'restored Redis authority cleanup';ACTIVE=''
set +e;JC_FL_E2E_STATE_ROOT="$STATE_ROOT" JC_FL_E2E_TEST_FAIL_AT=after_redis_authority_written bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$STATE_ROOT/after_redis_authority_written.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ]||fail 'after_redis_authority_written did not fail';[ -z "$(find "$STATE_ROOT" -mindepth 1 -maxdepth 1 -type d -print -quit)" ]||fail 'published Redis authority did not close failed start'
for point in after_run_dir after_redis after_port_reservation after_mysql docker_created_no_id after_endpoint_discovery during_transport_state during_transport_evidence after_evidence;do
 set +e;JC_FL_E2E_STATE_ROOT="$STATE_ROOT" JC_FL_E2E_TEST_FAIL_AT="$point" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$STATE_ROOT/$point.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ]||fail "$point did not fail";d="$(find "$STATE_ROOT" -mindepth 1 -maxdepth 1 -type d|head -1)";if [ -n "$d" ];then ACTIVE="$d";[ -f "$d/evidence/start-failure.json" ]||fail "$point retained without evidence";jc_fl_test_run_cleanup "$d";ACTIVE='';fi
done
# Removal failure retains exact created ID and evidence; cleanup validates complete captured fixture immediately before removal.
set +e;JC_FL_E2E_STATE_ROOT="$STATE_ROOT" JC_FL_E2E_TEST_FAIL_AT=after_mysql JC_FL_E2E_TEST_DOCKER_RM_FAIL=1 bash "$ROOT/scripts/fair-launch/local-e2e/start.sh">"$STATE_ROOT/remove.out" 2>&1;rc=$?;set -e;[ "$rc" -ne 0 ];retained="$(find "$STATE_ROOT" -mindepth 1 -maxdepth 1 -type d|head -1)";ACTIVE="$retained";[ "$(stat -Lc '%a' "$retained" "$retained/evidence/start-failure.json")" = $'700\n600' ];grep -Fq mysql-remove-failed "$retained/evidence/start-failure.json";source="$retained/evidence/docker-created.source.json";id="$(python3 "$JC_FL_TEST_CLEANUP_PY" container-static-verify "$source")";jc_fl_test_container_record "$id" "$(basename "$retained")" mysql "$retained" "$retained/evidence/test-container-cleanup.json"
# Mutated cleanup record is rejected and the live container survives.
cp "$retained/evidence/test-container-cleanup.json" "$retained/evidence/test-container-stale.json";python3 - "$retained/evidence/test-container-stale.json" <<'PY'
import json,sys
p=sys.argv[1];o=json.load(open(p));o['projectionDigest']='0'*64;open(p,'w').write(json.dumps(o)+'\n')
PY
chmod 600 "$retained/evidence/test-container-stale.json";set +e;jc_fl_test_container_remove "$retained/evidence/test-container-stale.json";stale_rc=$?;set -e;[ "$stale_rc" -ne 0 ];docker -H unix:///var/run/docker.sock inspect "$id">/dev/null;jc_fl_test_run_cleanup "$retained";ACTIVE=''
# Endpoint takeover after exact Redis exit fails cleanup, preserves state, and never signals the foreign listener.
out="$(JC_FL_E2E_STATE_ROOT="$STATE_ROOT" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh")";run="$(printf '%s\n' "$out"|sed -n 's/^RUN_ID=//p')";d="$STATE_ROOT/$run";ACTIVE="$d";redis_endpoint="$(python3 -c 'import json,sys;print(json.load(open(sys.argv[1]))["endpoint"])' "$d/redis/process.json")";redis_port="${redis_endpoint#127.0.0.1:}";mkdir -p "$d/test-hooks";hook="$d/test-hooks/redis-takeover.sh";cat >"$hook" <<'HOOK'
#!/usr/bin/env bash
python3 - "$REDIS_PORT" "$RUN_DIR/redis-takeover.marker" "$RUN_DIR/redis-takeover.pid" <<'PY' &
import os,socket,sys,time
port=int(sys.argv[1]);marker,pidf=sys.argv[2:];s=socket.socket();s.setsockopt(socket.SOL_SOCKET,socket.SO_REUSEADDR,1);s.bind(('127.0.0.1',port));s.listen();open(marker,'w').write('redis-endpoint-takeover\n');os.chmod(marker,0o600);open(pidf,'w').write(str(os.getpid())+'\n');os.chmod(pidf,0o600);time.sleep(120)
PY
for _ in $(seq 1 100);do [ -s "$RUN_DIR/redis-takeover.pid" ]&&break;sleep .05;done
HOOK
chmod 700 "$hook";set +e;JC_FL_E2E_TEST_REDIS_AFTER_EXIT_HOOK="$hook" jc_fl_test_redis_remove "$d";takeover_rc=$?;set -e;[ "$takeover_rc" -ne 0 ];[ -f "$d/redis/process.json" ];takeover_pid="$(cat "$d/redis-takeover.pid")";kill -0 "$takeover_pid";jc_fl_test_process_record "$takeover_pid" "$d/redis-takeover.marker" "$redis_endpoint" "$d" "$d/evidence/redis-takeover.json";ACTIVE_PROCESS="$d/evidence/redis-takeover.json";jc_fl_test_process_remove "$ACTIVE_PROCESS" TERM;ACTIVE_PROCESS='';jc_fl_test_run_cleanup "$d";ACTIVE=''
# Stale Redis start fingerprint refuses signal while the exact replacement remains live; canonical teardown removes it.
out="$(JC_FL_E2E_STATE_ROOT="$STATE_ROOT" bash "$ROOT/scripts/fair-launch/local-e2e/start.sh")";run="$(printf '%s\n' "$out"|sed -n 's/^RUN_ID=//p')";d="$STATE_ROOT/$run";ACTIVE="$d";cp "$d/redis/process.json" "$d/redis/process.stale";chmod 600 "$d/redis/process.stale";set +e;jc_fl_test_redis_remove "$d" "$d/redis/process.stale";stale_rc=$?;set -e;[ "$stale_rc" -ne 0 ];RUN_DIR="$d";REDIS_CONFIG="$d/redis/redis.conf";REDIS_FINGERPRINT="$d/redis/process.json";jc_fl_e2e_redis_owned "$REDIS_FINGERPRINT";jc_fl_test_bounded_teardown "$STATE_ROOT" "$run";ACTIVE='';jc_fl_test_root_finalize "$STATE_ROOT";trap - EXIT
 echo 'fair_launch_local_e2e_start_fault_test: PASS authoritative ID, immutable container cleanup, and stale Redis/container refusal'
